CREATE TABLE IF NOT EXISTS `household` (`id` TEXT NOT NULL, `currency` TEXT NOT NULL, `timeZone` TEXT NOT NULL, `reminderTime` TEXT NOT NULL, `openingSpendableCents` INTEGER NOT NULL, `openingSavingsCents` INTEGER NOT NULL, `openingDate` TEXT NOT NULL, `monthlySavingsTargetCents` INTEGER, `revision` INTEGER NOT NULL, PRIMARY KEY(`id`))
CREATE TABLE IF NOT EXISTS `categories` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `active` INTEGER NOT NULL, `revision` INTEGER NOT NULL, `deletedAt` TEXT, PRIMARY KEY(`id`))
CREATE TABLE IF NOT EXISTS `ledger_entries` (`id` TEXT NOT NULL, `kind` TEXT NOT NULL, `entryDate` TEXT NOT NULL, `amountCents` INTEGER NOT NULL, `categoryId` TEXT, `account` TEXT, `note` TEXT, `occurrenceId` TEXT, `revision` INTEGER NOT NULL, `deletedAt` TEXT, PRIMARY KEY(`id`))
CREATE INDEX IF NOT EXISTS `index_ledger_entries_entryDate` ON `ledger_entries` (`entryDate`)
CREATE INDEX IF NOT EXISTS `index_ledger_entries_categoryId` ON `ledger_entries` (`categoryId`)
CREATE TABLE IF NOT EXISTS `monthly_estimates` (`id` TEXT NOT NULL, `categoryId` TEXT NOT NULL, `month` TEXT NOT NULL, `amountCents` INTEGER NOT NULL, `revision` INTEGER NOT NULL, `deletedAt` TEXT, PRIMARY KEY(`id`))
CREATE INDEX IF NOT EXISTS `index_monthly_estimates_month` ON `monthly_estimates` (`month`)
CREATE UNIQUE INDEX IF NOT EXISTS `index_monthly_estimates_month_categoryId` ON `monthly_estimates` (`month`, `categoryId`)
CREATE TABLE IF NOT EXISTS `monthly_plans` (`id` TEXT NOT NULL, `month` TEXT NOT NULL, `savingsTargetCents` INTEGER, `revision` INTEGER NOT NULL, `deletedAt` TEXT, PRIMARY KEY(`id`))
CREATE UNIQUE INDEX IF NOT EXISTS `index_monthly_plans_month` ON `monthly_plans` (`month`)
CREATE TABLE IF NOT EXISTS `recurring_rules` (`id` TEXT NOT NULL, `kind` TEXT NOT NULL, `name` TEXT NOT NULL, `categoryId` TEXT, `amountCents` INTEGER NOT NULL, `frequency` TEXT NOT NULL, `interval` INTEGER NOT NULL, `startsOn` TEXT NOT NULL, `endsOn` TEXT, `scheduleDetailsJson` TEXT, `active` INTEGER NOT NULL, `revision` INTEGER NOT NULL, `deletedAt` TEXT, PRIMARY KEY(`id`))
CREATE INDEX IF NOT EXISTS `index_recurring_rules_startsOn` ON `recurring_rules` (`startsOn`)
CREATE TABLE IF NOT EXISTS `occurrences` (`id` TEXT NOT NULL, `ruleId` TEXT NOT NULL, `ruleName` TEXT NOT NULL, `ruleKind` TEXT NOT NULL, `expectedDate` TEXT NOT NULL, `expectedAmountCents` INTEGER NOT NULL, `status` TEXT NOT NULL, `actualDate` TEXT, `actualAmountCents` INTEGER, `confirmationMethod` TEXT, `needsReview` INTEGER NOT NULL, `revision` INTEGER NOT NULL, `deletedAt` TEXT, PRIMARY KEY(`id`))
CREATE INDEX IF NOT EXISTS `index_occurrences_expectedDate` ON `occurrences` (`expectedDate`)
CREATE INDEX IF NOT EXISTS `index_occurrences_ruleId` ON `occurrences` (`ruleId`)
CREATE TABLE IF NOT EXISTS `devices` (`id` TEXT NOT NULL, `label` TEXT NOT NULL, `pairedAt` TEXT NOT NULL, `revokedAt` TEXT, PRIMARY KEY(`id`))
CREATE TABLE IF NOT EXISTS `sync_state` (`householdId` TEXT NOT NULL, `cursor` TEXT NOT NULL, PRIMARY KEY(`householdId`))
CREATE TABLE IF NOT EXISTS `pending_operations` (`operationId` TEXT NOT NULL, `entityId` TEXT NOT NULL, `entityType` TEXT NOT NULL, `action` TEXT NOT NULL, `baseRevision` INTEGER NOT NULL, `valueJson` TEXT, `createdAt` TEXT NOT NULL, `state` TEXT NOT NULL, `errorCode` TEXT, PRIMARY KEY(`operationId`))
CREATE INDEX IF NOT EXISTS `index_pending_operations_createdAt` ON `pending_operations` (`createdAt`)
CREATE TABLE IF NOT EXISTS `sync_conflicts` (`id` TEXT NOT NULL, `entityType` TEXT NOT NULL, `entityId` TEXT NOT NULL, `serverValueJson` TEXT, `proposedValueJson` TEXT NOT NULL, `createdAt` TEXT NOT NULL, PRIMARY KEY(`id`))
CREATE INDEX IF NOT EXISTS `index_sync_conflicts_entityId` ON `sync_conflicts` (`entityId`)